#!/usr/bin/env bash
# generate_consensus.sh — merge PHYLIP consense results into the
# bootstrap consensus fixtures (v1.2).
#
# Every JSON in fixtures/consensus/ (generated by generate.R) plus the
# hand-entered fixtures/worked/consensus_hand.json carries a `trees` list.
# Each is run through PHYLIP consense three times: extended majority (the
# default), strict (one C toggle) and plain majority rule (two C toggles)
# — the menu output is read to confirm the toggles, never assumed — and
# with option R for rooted sets. The outfile set tables and the outtree
# are parsed back into the JSON under `consense.<kind>`.
#
# In R (same heredoc) the script asserts that the consense group inventory
# equals the prop.part inventory of `trees`, that strict = unanimous sets,
# majority = >50% sets, and that no extended-majority decision is tied; it
# fails on any mismatch or tie.
#
# Invoked at the end of generate_phylip.sh; can also run standalone.
# Requires: consense (on PATH or /usr/lib/phylip/bin), Rscript with
# jsonlite + ape.

set -euo pipefail

FIXDIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

find_phylip() {
  if command -v "$1" >/dev/null 2>&1; then command -v "$1";
  elif [ -x "/usr/lib/phylip/bin/$1" ]; then echo "/usr/lib/phylip/bin/$1";
  else echo "missing PHYLIP binary: $1 (install the phylip package)" >&2; exit 1; fi
}
CONSENSE="$(find_phylip consense)"

TMPD="$(mktemp -d)"
trap 'rm -rf "$TMPD"' EXIT
cd "$TMPD"

# $1 = extended|strict|majority, $2 = rooted(true|false)
# ./intree must exist; produces ./outfile and ./outtree.
run_consense() {
  rm -f outfile outtree
  local keys=""
  [ "$2" = true ] && keys="R\n"
  case "$1" in
    extended) keys="${keys}Y\n" ;;
    strict)   keys="${keys}C\nY\n" ;;
    majority) keys="${keys}C\nC\nY\n" ;;
    *) echo "unknown consense kind: $1" >&2; exit 1 ;;
  esac
  printf "$keys" | timeout 120 "$CONSENSE" > phylip.log 2>&1
  [ -f outfile ] && [ -f outtree ] || {
    cat phylip.log; echo "consense produced no outfile/outtree" >&2; exit 1; }

  # Confirm the toggles landed, from the menu echo — never assumed. The
  # menu line always lists all four consensus types in parens, so match
  # only the value after ":  ".
  local tline rline
  tline="$(grep 'Consensus type' phylip.log | tail -1)"
  case "$1" in
    extended)
      case "$tline" in *":  Majority rule (extended)") : ;; *)
        cat phylip.log; echo "consense: expected extended majority, got: $tline" >&2; exit 1 ;; esac ;;
    strict)
      case "$tline" in *":  strict") : ;; *)
        cat phylip.log; echo "consense: expected strict, got: $tline" >&2; exit 1 ;; esac ;;
    majority)
      case "$tline" in *":  Majority rule") : ;; *)
        cat phylip.log; echo "consense: expected majority rule, got: $tline" >&2; exit 1 ;; esac ;;
  esac
  rline="$(grep 'treated as Rooted' phylip.log | tail -1)"
  if [ "$2" = true ]; then
    case "$rline" in *Yes*) : ;; *)
      cat phylip.log; echo "consense: R toggle did not land: $rline" >&2; exit 1 ;; esac
  else
    case "$rline" in *No*) : ;; *)
      cat phylip.log; echo "consense: unexpected rooted setting: $rline" >&2; exit 1 ;; esac
  fi
}

CVER=""
for json in "$FIXDIR"/consensus/*.json "$FIXDIR"/worked/consensus_hand.json; do
  [ -e "$json" ] || continue
  name="$(basename "$json" .json)"

  # intree: one Newick per line, straight from the JSON.
  Rscript - "$json" intree <<'RS'
a <- commandArgs(trailingOnly = TRUE)
writeLines(jsonlite::fromJSON(a[1])$trees, a[2])
RS
  rooted="$(Rscript -e 'cat(tolower(jsonlite::fromJSON(commandArgs(TRUE)[1])$rooted))' "$json")"

  for kind in extended strict majority; do
    run_consense "$kind" "$rooted"
    [ -n "$CVER" ] || CVER="$(grep -o 'version [0-9.]*' phylip.log | head -1 | awk '{print $2}')"
    cp "outfile" "cons_${kind}.out"
    cp "outtree" "cons_${kind}.nwk"
  done

  JSON="$json" GEN="phylip $CVER" Rscript - <<'RS'
suppressPackageStartupMessages({library(ape); library(jsonlite)})
json_path <- Sys.getenv("JSON"); gen <- Sys.getenv("GEN")
j <- fromJSON(json_path)
labs <- j$labels; rooted <- isTRUE(j$rooted)
trees <- lapply(j$trees, function(s) read.tree(text = s))

# --- consense outfile parser -------------------------------------------
# "Species in order" maps mask positions to labels; "Sets included in the
# consensus tree" and "Sets NOT included in consensus tree" hold rows of
# `..*.**` masks plus a count.
parse_outfile <- function(path) {
  lines <- readLines(path)
  i <- grep("Species in order", lines)[1]
  j2 <- grep("Sets included in the consensus tree", lines)[1]
  stopifnot(!is.na(i), !is.na(j2))
  # The species list wraps every 10 entries (blank separator lines), so
  # collect every "  k. name" line up to the first table header and index
  # it by its number.
  sp <- character(0)
  for (ln in lines[(i + 1):(j2 - 1)]) {
    m <- regmatches(ln, regexec("^\\s*(\\d+)\\.\\s+(\\S+)\\s*$", ln))[[1]]
    if (length(m) == 3) sp[as.integer(m[2])] <- m[3]
  }
  stopifnot(!any(is.na(sp)))
  totals <- grep("How many times out of", lines, value = TRUE)
  stopifnot(length(totals) >= 1)
  total <- as.numeric(sub(".*out of\\s+", "", totals[1]))

  # Set rows: mask groups of up to 10 '*'/'.' chars, single-space
  # separated, then a wide gap and the count.
  inc <- list(); exc <- list(); mode <- NULL
  for (ln in lines) {
    if (grepl("Sets included in the consensus tree", ln)) { mode <- "i"; next }
    if (grepl("Sets NOT included", ln)) { mode <- "o"; next }
    m <- regmatches(ln, regexec("^\\s*([*.]+(?: [*.]+)*)\\s{2,}([0-9.]+)\\s*$",
                              ln))[[1]]
    if (length(m) == 3 && !is.null(mode)) {
      mask <- strsplit(gsub(" ", "", m[2]), "", fixed = TRUE)[[1]]
      stopifnot(length(mask) == length(sp))
      g <- list(labels = sort(sp[mask == "*"]),
                count = round(as.numeric(m[3])))
      if (mode == "i") inc[[length(inc) + 1]] <- g
      else             exc[[length(exc) + 1]] <- g
    }
  }
  list(inc = inc, exc = exc, species = sp, total = total)
}

read_nwk <- function(path) gsub("\\s+", "", paste(readLines(path), collapse = ""))

# --- inventory from the trees (same canonicalization as generate.R) ----
# Canonical side for unrooted splits: the side NOT containing the first
# fixture label (taxon 0). consense happens to print the side not
# containing ITS species 1 (the first tip of the intree), which may
# differ — the rows are re-canonicalized below.
canon_side <- function(idx, plabs, labs, rooted) {
  side <- plabs[idx]
  if (!rooted && labs[1] %in% side) side <- setdiff(labs, side)
  sort(side)
}
grouping_inventory <- function(trees, labs, rooted) {
  pp <- do.call(prop.part, unname(trees))
  plabs <- attr(pp, "labels"); num <- attr(pp, "number")
  stopifnot(!is.null(plabs), !is.null(num), setequal(plabs, labs))
  inv <- new.env(parent = emptyenv())
  for (i in seq_along(pp)) {
    side <- canon_side(pp[[i]], plabs, labs, rooted)
    if (length(side) < 2 || length(side) == length(labs)) next
    key <- paste(side, collapse = "\x1f")
    if (exists(key, envir = inv, inherits = FALSE)) {
      inv[[key]]$count <- inv[[key]]$count + num[i]
    } else inv[[key]] <- list(labels = side, count = num[i])
  }
  inv
}
grp_compat <- function(a, b, n, rooted) {
  if (rooted) {
    i <- length(intersect(a, b))
    return(i == 0 || i == length(a) || i == length(b))
  }
  ab <- length(intersect(a, b))
  min(ab, length(a) - ab, length(b) - ab, n - length(a) - length(b) + ab) == 0
}
key_of <- function(g) paste(g$labels, collapse = "\x1f")

outs <- list()
for (kind in c("extended", "strict", "majority"))
  outs[[kind]] <- parse_outfile(paste0("cons_", kind, ".out"))

for (kind in c("extended", "strict", "majority")) {
  o <- outs[[kind]]
  if (!setequal(o$species, labs) || length(o$species) != length(labs) ||
      o$total != length(trees)) {
    cat("kind:", kind, "\nspecies:", o$species, "\nlabs:", labs,
        "\ntotal:", o$total, "ntrees:", length(trees), "\n")
    stop("consense species table does not match the fixture labels")
  }
}

# Re-canonicalize unrooted sides (see the note above canon_side).
if (!rooted) {
  recanon <- function(o) {
    for (fld in c("inc", "exc")) {
      o[[fld]] <- lapply(o[[fld]], function(g) {
        if (labs[1] %in% g$labels) g$labels <- sort(setdiff(labs, g$labels))
        g
      })
    }
    o
  }
  outs <- lapply(outs, recanon)
}

inv <- grouping_inventory(trees, labs, rooted)
inv_keys <- ls(envir = inv, all.names = TRUE)
inv_counts <- vapply(inv_keys, function(k) inv[[k]]$count, numeric(1))
names(inv_counts) <- inv_keys
ntax <- length(labs); total <- length(trees)

# The extended table (included + NOT included) is the full inventory.
ext <- c(outs$extended$inc, outs$extended$exc)
ext_counts <- vapply(ext, function(g) g$count, numeric(1))
names(ext_counts) <- vapply(ext, key_of, "")
if (!identical(sort(names(ext_counts)), sort(inv_keys)) ||
    !identical(ext_counts[sort(names(ext_counts))],
               inv_counts[sort(names(ext_counts))])) {
  cat("inventory mismatch in", json_path, "\nconsense:", sort(names(ext_counts)),
      "\nours:", sort(inv_keys), "\n")
  stop("consense group inventory does not match prop.part")
}

# strict = unanimous sets; majority = strictly more than half.
in_keys <- function(o) vapply(o$inc, key_of, "")
unanimous <- inv_keys[inv_counts == total]
maj_keys  <- inv_keys[inv_counts > total / 2]
stopifnot(setequal(in_keys(outs$strict), unanimous),
          setequal(in_keys(outs$majority), maj_keys))

# Extended majority: simulate spec §3.5 on the inventory — majority sets,
# then remaining sets by decreasing count, adding each if compatible,
# stopping when the tree is fully resolved (n-3 splits unrooted, n-2
# clades rooted — consense stops there too) — and assert (a) no decision
# is tied, (b) the result equals consense.
all_sets <- mget(inv_keys, envir = inv, inherits = FALSE)
acc <- all_sets[inv_counts > total / 2]
resolved <- if (rooted) ntax - 2 else ntax - 3
for (c in sort(unique(inv_counts[inv_counts <= total / 2]),
               decreasing = TRUE)) {
  if (length(acc) == resolved) break
  cand <- all_sets[inv_counts == c]
  cand <- Filter(function(s) all(vapply(acc, function(t)
    grp_compat(s$labels, t$labels, ntax, rooted), TRUE)), cand)
  if (length(cand) > 1) {
    for (x in seq_len(length(cand) - 1)) {
      for (y in (x + 1):length(cand)) {
        if (!grp_compat(cand[[x]]$labels, cand[[y]]$labels, ntax, rooted))
          stop("tie at an extended-majority decision in ", json_path,
               ": count ", c, " -> (",
               paste(cand[[x]]$labels, collapse = ","), ") vs (",
               paste(cand[[y]]$labels, collapse = ","), ")")
      }
    }
  }
  acc <- c(acc, cand)
}
stopifnot(setequal(vapply(acc, key_of, ""), in_keys(outs$extended)))

groups_of <- function(o) c(o$inc, o$exc)
j$consense <- list(
  generator = gen,
  strict    = list(newick = read_nwk("cons_strict.nwk"),
                   groups = groups_of(outs$strict)),
  majority  = list(newick = read_nwk("cons_majority.nwk"),
                   groups = groups_of(outs$majority)),
  extended  = list(newick = read_nwk("cons_extended.nwk"),
                   groups = groups_of(outs$extended))
)
writeLines(toJSON(j, auto_unbox = TRUE, digits = NA, pretty = TRUE),
           json_path)
cat(sprintf("%s: %d taxa, %d trees, %d groupings -> consense merged\n",
            j$name, ntax, total, length(inv_keys)))
RS
done
